/// Render an icon path as the same `<svg>` the reference emits.
///
/// `d` accepts a plain path const or a signal of one — a signal swaps the
/// path in place (eye/eye-off toggles) without re-rendering the `<svg>`
/// (approved API change, 2026-08-07; frozen again).
#[component]
pub fn Icon(
    #[prop(into)] d: Signal<&'static str>,
    #[prop(optional, into)] class: Option<String>,
) -> impl IntoView {
    view! {
        <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class=class.unwrap_or_default()>
            <path d=move || d.get()></path>
        </svg>
    }
}

